import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>

constexpr int BM = 128;
constexpr int BN = 128;
constexpr int BK = 16;
constexpr int TM = 8;
constexpr int TN = 8;
constexpr int THREADS = 256;
constexpr int STAGES = 3;
constexpr int LK = BK;
constexpr int LDB = BN;
__device__ __forceinline__ void cp_async16(void* smem_dst, const void* gmem_src) {
    const unsigned dst = static_cast<unsigned>(__cvta_generic_to_shared(smem_dst));
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" ::"r"(dst), "l"(gmem_src));
}
__device__ __forceinline__ void cp_async_commit() {
    asm volatile("cp.async.commit_group;\n");
}
template <int REM>
__device__ __forceinline__ void cp_async_wait() {
    asm volatile("cp.async.wait_group %0;\n" ::"n"(REM));
}
__device__ __forceinline__ void load_tile_async(const float* __restrict__ A,
                                                const float* __restrict__ B,
                                                int N,
                                                int block_m,
                                                int block_n,
                                                int k0,
                                                int tid,
                                                float As[BM][LK],
                                                float Bs[BK][LDB]) {
    #pragma unroll
    for (int it = 0; it < 2; ++it) {
        const int idx = tid + (it << 8);
        const int a_m = idx >> 2;
        const int a_k4 = idx & 3;
        const int b_k = idx >> 5;
        const int b_n4 = idx & 31;
        cp_async16(&As[a_m][a_k4 << 2],
                   A + (long long)(block_m + a_m) * N + k0 + (a_k4 << 2));
        cp_async16(&Bs[b_k][b_n4 << 2],
                   B + (long long)(k0 + b_k) * N + block_n + (b_n4 << 2));
    }
}
__global__ __launch_bounds__(THREADS)
void square_matmul_kernel(const float* __restrict__ A,
                          const float* __restrict__ B,
                          float* __restrict__ C,
                          int N) {
    __shared__ __align__(16) float As[STAGES][BM][LK];
    __shared__ __align__(16) float Bs[STAGES][BK][LDB];
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = (ty << 4) + tx;
    const int block_m = blockIdx.y * BM;
    const int block_n = blockIdx.x * BN;
    const int row0 = block_m + ty * TM;
    const int col0 = block_n + tx * TN;
    const int lr0 = ty * TM;
    const int lc0 = tx * TN;
    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            acc[i][j] = 0.0f;
        }
    }
    int k_load = 0;
    #pragma unroll
    for (int s = 0; s < STAGES - 1; ++s) {
        load_tile_async(A, B, N, block_m, block_n, k_load, tid, As[s], Bs[s]);
        cp_async_commit();
        k_load += BK;
    }
    int curr = 0;
    for (int k0 = 0; k0 < N; k0 += BK) {
        cp_async_wait<STAGES - 2>();
        __syncthreads();
        if (k_load < N) {
            const int nxt = (curr == 0) ? (STAGES - 1) : (curr - 1);
            load_tile_async(A, B, N, block_m, block_n, k_load, tid, As[nxt], Bs[nxt]);
        }
        cp_async_commit();
        k_load += BK;
        #pragma unroll
        for (int kk4 = 0; kk4 < (BK >> 2); ++kk4) {
            float a_frag[TM][4];
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                *reinterpret_cast<float4*>(a_frag[i]) =
                    *reinterpret_cast<const float4*>(&As[curr][lr0 + i][kk4 << 2]);
            }
            #pragma unroll
            for (int kkk = 0; kkk < 4; ++kkk) {
                const int kk = (kk4 << 2) + kkk;
                const float4 bv0 = *reinterpret_cast<const float4*>(&Bs[curr][kk][lc0]);
                const float4 bv1 = *reinterpret_cast<const float4*>(&Bs[curr][kk][lc0 + 4]);
                const float bf[TN] = {bv0.x, bv0.y, bv0.z, bv0.w,
                                      bv1.x, bv1.y, bv1.z, bv1.w};
                #pragma unroll
                for (int i = 0; i < TM; ++i) {
                    #pragma unroll
                    for (int j = 0; j < TN; ++j) {
                        acc[i][j] += a_frag[i][kkk] * bf[j];
                    }
                }
            }
        }
        __syncthreads();
        curr = (curr == STAGES - 1) ? 0 : (curr + 1);
    }
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        const float4 out0 = make_float4(acc[i][0], acc[i][1], acc[i][2], acc[i][3]);
        const float4 out1 = make_float4(acc[i][4], acc[i][5], acc[i][6], acc[i][7]);
        *reinterpret_cast<float4*>(C + (long long)(row0 + i) * N + col0) = out0;
        *reinterpret_cast<float4*>(C + (long long)(row0 + i) * N + col0 + 4) = out1;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32 &&
                B.scalar_type() == torch::kFloat32,
                "A and B must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.is_contiguous() && B.is_contiguous(),
                "A and B must be contiguous");

    const int64_t N64 = A.size(0);
    TORCH_CHECK(A.size(1) == N64 && B.size(0) == N64 && B.size(1) == N64,
                "A and B must be square matrices with matching N");
    TORCH_CHECK(N64 <= INT32_MAX, "N is too large");
    TORCH_CHECK(N64 % BM == 0, "This kernel expects N to be divisible by 64");

    const c10::cuda::CUDAGuard device_guard(A.device());
    torch::Tensor C = torch::empty_like(A);

    const int N = static_cast<int>(N64);
    dim3 block(16, 16);
    dim3 grid(N / BN, N / BM);

    square_matmul_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, cudaGetErrorString(err));
    return C;
}
"""

_cpp_src = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

_ext = load_inline(
    name="square_matmul_cuda_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["matmul_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return _ext.matmul_cuda(A, B)

